package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct {
	DrItem  string
	DrPrice decimal.Decimal
	DrPct   int64
}

var WsEofFlag string
var WsDiscount decimal.Decimal
var WsNet decimal.Decimal
var WsTotalNet decimal.Decimal
var WsCount int64
var WsPriceEd string
var WsDiscEd string
var WsNetEd string
var WsTotalEd string

var discRec DiscRec
var inputDone bool
var reader *bufio.Reader
var file *os.File

func storeDecimal(v decimal.Decimal, intDigits int, fracDigits int, rounded bool) decimal.Decimal {
	if rounded {
		v = v.Round(int32(fracDigits))
	} else {
		v = v.Truncate(int32(fracDigits))
	}
	totalDigits := intDigits + fracDigits
	if totalDigits == 0 {
		return decimal.Zero
	}
	// Scale to integer
	scaled := v.Shift(int32(fracDigits))
	// Truncate to integer (should already be integral after Round/Truncate)
	scaled = scaled.Truncate(0)
	modPow := decimal.New(1, int32(totalDigits))
	// keep low-order digits: modulo for positive numbers
	// decimal.Mod needs positive
	if scaled.IsNegative() {
		// For negative, COBOL keeps sign and low-order digits; not needed for this program (all positive)
		// Implement as: absolute mod then re-apply sign
		neg := scaled.Abs().Mod(modPow)
		scaled = neg.Neg()
	} else {
		scaled = scaled.Mod(modPow)
	}
	result := scaled.Shift(int32(-fracDigits))
	// Ensure scale is exactly fracDigits (for formatting consistency, keep trailing zeros)
	// Truncate will keep scale; but we want correct scale
	if fracDigits > 0 {
		result = result.Truncate(int32(fracDigits))
	}
	return result
}

func storeInt(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// keep low-order digits, handle negative not needed
	if v < 0 {
		av := -v
		av = av % mod
		return -av
	}
	return v % mod
}

func formatEdited(v decimal.Decimal, picture string) string {
	// Parse picture to count integer digits (Z+9 before dot) and fractional digits after dot
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	fracDigits := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracDigits++
		}
	}
	// Prepare digits strings for integer and fractional parts
	// Ensure v is truncated to fracDigits (should already)
	// Get absolute value string with exactly fracDigits fractional digits
	// Use truncation logic already applied; just format
	// To handle overflow of integer digits, keep low-order digits
	// Derive integer part as scaled integer
	scaled := v.Shift(int32(fracDigits)).Truncate(0)
	// scaled may be negative? not here
	isNeg := scaled.IsNegative()
	if isNeg {
		scaled = scaled.Abs()
	}
	// total integer magnitude
	// For overflow we already truncated stored value, but formatting also must drop high-order if still overflow
	// So we take scaled % 10^(intDigits+fracDigits) then split
	totalDigits := intDigits + fracDigits
	if totalDigits > 0 {
		modPow := decimal.New(1, int32(totalDigits))
		scaled = scaled.Mod(modPow)
	}
	// Convert scaled to int string zero-padded to totalDigits
	s := scaled.String() // no exponent, decimal library may include exponent but scaled is integer
	// scaled.String() for integer decimal returns like "1234"
	// Pad
	if len(s) < totalDigits {
		s = strings.Repeat("0", totalDigits-len(s)) + s
	} else if len(s) > totalDigits {
		s = s[len(s)-totalDigits:]
	}
	intStr := ""
	fracStr := ""
	if totalDigits > 0 {
		if fracDigits > 0 {
			if intDigits > 0 {
				intStr = s[:intDigits]
				fracStr = s[intDigits:]
			} else {
				intStr = ""
				fracStr = s
			}
		} else {
			intStr = s
			fracStr = ""
		}
	}
	// Now map digits into picture
	// Build output rune slice from picture
	out := []rune(picture)
	// Fill integer digit positions
	idxInt := 0 // index into intStr
	for i, c := range out {
		if c == 'Z' || c == '9' {
			// Determine if this position is before dot
			// Find if i is before dotIdx (if dot present)
			isIntPos := false
			if dotIdx >= 0 {
				isIntPos = i < dotIdx
			} else {
				isIntPos = true
			}
			if isIntPos {
				if idxInt < len(intStr) {
					out[i] = rune(intStr[idxInt])
					idxInt++
				} else {
					out[i] = '0'
				}
			} else {
				// fractional part
				// fractional digits are after dot; we need separate index
				// Use frac index
			}
		}
	}
	// Fill fractional digit positions
	idxFrac := 0
	for i, c := range picture {
		if c == 'Z' || c == '9' {
			// fractional if after dot
			if dotIdx >= 0 && i > dotIdx {
				if idxFrac < len(fracStr) {
					out[i] = rune(fracStr[idxFrac])
					idxFrac++
				} else {
					out[i] = '0'
				}
			}
		}
	}
	// Apply Z suppression for integer part
	// suppression continues while all previous Z digits were zero and replaced with space
	suppressing := true
	for i := 0; i < len(out); i++ {
		// stop at dot
		if dotIdx >= 0 && i == dotIdx {
			break
		}
		pc := rune(picture[i])
		if pc == ',' {
			if suppressing {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		} else if pc == 'Z' {
			if suppressing && out[i] == '0' {
				out[i] = ' '
			} else {
				suppressing = false
				// keep digit as is (already)
			}
		} else if pc == '9' {
			// This is an integer 9 position (before dot); it ends suppression
			suppressing = false
			// keep digit
		}
	}
	// Sign handling not needed (all positive)
	_ = isNeg
	return string(out)
}

func mainPara() {
	var err error
	file, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	reader = bufio.NewReader(file)
	readPara()
	for !inputDone {
		processPara()
	}
	file.Close()
	summaryPara()
}

func readPara() {
	line, err := reader.ReadString('\n')
	if err != nil {
		// EOF or other; if we got some data before error, process it
		if len(line) == 0 {
			WsEofFlag = "Y"
			inputDone = true
			return
		}
		// line without newline at EOF is still a record
	}
	// Strip trailing newline \r\n
	line = strings.TrimRight(line, "\r\n")
	// Pad with spaces to 15 if shorter
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	// Parse fields
	drItem := line[0:6]
	drPriceRaw := line[6:13]
	drPctRaw := line[13:15]

	// DR-PRICE digits only
	sPrice := strings.TrimSpace(drPriceRaw)
	// If contains non-digit, treat as 0? Assume digits
	var priceInt int64
	if sPrice == "" {
		priceInt = 0
	} else {
		// sPrice should be 7 digits, may contain spaces
		// Remove spaces
		sPrice = strings.ReplaceAll(sPrice, " ", "0")
		// Actually spaces should be treated as 0? But pad with spaces case already covered.
		// Parse
		priceInt, _ = strconv.ParseInt(sPrice, 10, 64)
	}
	drPrice := decimal.New(priceInt, -2)

	sPct := strings.TrimSpace(drPctRaw)
	var pctInt int64
	if sPct == "" {
		pctInt = 0
	} else {
		sPct = strings.ReplaceAll(sPct, " ", "0")
		pctInt, _ = strconv.ParseInt(sPct, 10, 64)
		pctInt = storeInt(pctInt, 2)
	}

	discRec.DrItem = drItem
	discRec.DrPrice = drPrice
	discRec.DrPct = pctInt

	if err != nil && len(line) == 15 {
		// we read successfully, but next read will be EOF
		// Actually we already consumed a line that had no newline; next read will be EOF
		// To mimic COBOL, we should not set EOF yet; we have a valid record
		// So do nothing; next read will set EOF
		// But if err was EOF and line was empty, handled above
		// If err is EOF and line had data, we have valid record, keep inputDone false
		// However we lost the ability to know EOF. We'll set a flag to indicate next read is EOF
		// Simpler: if err != nil (EOF) and we have data, we keep flag and next read will hit EOF
		// But our reader will return EOF on next call anyway
	} else if err != nil {
		// shouldn't happen
	}
	// If err == nil, we have valid record, inputDone remains false
	// If this line was the last without newline, we still have valid record; mark that next read will be EOF via no special handling
	// To avoid missing EOF detection, check if err != nil, we will need to handle next read
	// We can peek if err is EOF: next read will be EOF, but current record is valid
	// So leave inputDone false for now
	// However if err == io.EOF and line length was 0, we already returned
}

func processPara() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT /100
	pctDec := decimal.New(discRec.DrPct, 0)
	rawDiscount := discRec.DrPrice.Mul(pctDec).Shift(-2)
	WsDiscount = storeDecimal(rawDiscount, 5, 2, true)
	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	rawNet := discRec.DrPrice.Sub(WsDiscount)
	WsNet = storeDecimal(rawNet, 5, 2, false)
	// ADD WS-NET TO WS-TOTAL-NET
	rawTotal := WsTotalNet.Add(WsNet)
	WsTotalNet = storeDecimal(rawTotal, 8, 2, false)
	// ADD 1 TO WS-COUNT
	WsCount = storeInt(WsCount+1, 3)
	// MOVE DR-PRICE TO WS-PRICE-ED etc
	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")
	// DISPLAY DR-ITEM " " WS-PRICE-ED " " DR-PCT "% " WS-DISC-ED " " WS-NET-ED
	pctStr := fmt.Sprintf("%02d", discRec.DrPct)
	fmt.Printf("%s %s %s%% %s %s\n", discRec.DrItem, WsPriceEd, pctStr, WsDiscEd, WsNetEd)
	readPara()
}

func summaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	WsEofFlag = "N"
	WsDiscount = decimal.New(0, 0)
	WsNet = decimal.New(0, 0)
	WsTotalNet = decimal.New(0, 0)
	WsCount = 0
	inputDone = false
	mainPara()
}
